//! ICEM reference-motor sector mesh round-trip (issue #1162, motor paper M2).
//!
//! Loads the pinned coarse level-0 mesh generated by
//! `benchmarks/motor_reference/geometry/build_sector_mesh.py` through the
//! existing MSH reader ([`read_tagged_tri_mesh`]) and checks that the tags,
//! the per-region areas and the sliding-band coupling circle survive the
//! round trip:
//!
//! - every documented physical group is present under its tag and name;
//! - per-region triangle areas equal the generator's report (round trip)
//!   and sit within the generator-reported discretisation error of the
//!   exact NURBS area; the regions tile the annular sector;
//! - both sides of the coupling circle r_c = 44.5 mm carry N + 1 = 121
//!   distinct nodes on a uniform 0.5-degree grid, coincident pairwise;
//! - each antiperiodic radial edge maps onto its partner by the +60-degree
//!   rotation, node for node.

use std::f64::consts::PI;
use std::path::PathBuf;

use geode_core::mesh::{TaggedTriMesh, read_tagged_tri_mesh};
use serde_json::Value;

const R_I: f64 = 0.016;
const R_C: f64 = 0.0445;
const R_O: f64 = 0.0675;
const N_SEGMENTS: usize = 120;

fn geometry_dir() -> PathBuf {
    // CARGO_MANIFEST_DIR = crates/geode-core; benchmarks/ is at the repo root.
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../benchmarks/motor_reference/geometry")
}

fn load() -> (TaggedTriMesh, Value) {
    let dir = geometry_dir().join("meshes");
    let bytes = std::fs::read(dir.join("icem_initial_sector_L0.msh")).expect("read pinned mesh");
    let mesh = read_tagged_tri_mesh(&bytes).expect("parse pinned mesh");
    let report: Value = serde_json::from_slice(
        &std::fs::read(dir.join("icem_initial_sector_L0_report.json")).expect("read report"),
    )
    .expect("parse report");
    (mesh, report)
}

fn region_names() -> Vec<(&'static str, i32)> {
    vec![
        ("rotor_iron", 1),
        ("magnet", 2),
        ("rotor_air", 3),
        ("airgap_inner", 4),
        ("airgap_outer", 5),
        ("stator_iron", 6),
        ("slot_air", 7),
        ("winding_01_U+", 11),
        ("winding_02_U+", 12),
        ("winding_03_U+", 13),
        ("winding_04_U-", 14),
        ("winding_05_W-", 15),
        ("winding_06_W-", 16),
        ("winding_07_W-", 17),
        ("winding_08_W-", 18),
        ("winding_09_V+", 19),
        ("winding_10_V+", 20),
        ("winding_11_V+", 21),
        ("winding_12_V+", 22),
    ]
}

fn line_names() -> Vec<(&'static str, i32)> {
    vec![
        ("dirichlet_inner", 101),
        ("dirichlet_outer", 102),
        ("rotor_edge_lo", 111),
        ("rotor_edge_hi", 112),
        ("stator_edge_lo", 113),
        ("stator_edge_hi", 114),
        ("coupling_rotor", 121),
        ("coupling_stator", 122),
    ]
}

#[test]
fn tags_round_trip() {
    let (m, _) = load();
    for (name, tag) in region_names() {
        assert_eq!(m.physical_group_tag(2, name), Some(tag), "region {name}");
        assert!(!m.tris_with_tag(tag).is_empty(), "region {name} empty");
    }
    for (name, tag) in line_names() {
        assert_eq!(m.physical_group_tag(1, name), Some(tag), "line {name}");
        assert!(!m.lines_with_tag(tag).is_empty(), "line {name} empty");
    }
    // Every triangle is tagged.
    assert!(m.tri_physical_tags.iter().all(|&t| t != 0));
}

/// Judge finding on PR #1164: gmsh wrote 3051 of the 5938 L0 triangles
/// clockwise (patch parametrisations of both orientations). The reader must
/// hand every consumer counter-clockwise triangles, as the magnetostatic
/// assemblers assert `signed_area > 0`, without changing tags or areas.
#[test]
fn every_triangle_is_counter_clockwise_after_loading() {
    let (m, report) = load();
    assert_eq!(m.mesh.n_tris(), 5938);
    assert_eq!(
        m.reoriented_triangles, 3051,
        "clockwise triangles in the file"
    );
    for t in 0..m.mesh.n_tris() {
        let a = geode_core::mesh::tagged_tri::tri_signed_area(&m.mesh, t);
        assert!(a > 1e-14, "triangle {t} has signed area {a:e}");
    }
    // Per-region triangle counts are unchanged by re-orientation.
    for (name, tag) in region_names() {
        let n = m.tris_with_tag(tag).len();
        assert_eq!(
            Some(n as u64),
            report["regions"][name]["triangles"].as_u64(),
            "region {name}"
        );
    }
}

#[test]
fn region_areas_round_trip_and_tile_the_sector() {
    let (m, report) = load();
    let regions = &report["regions"];
    let mut total = 0.0;
    for (name, tag) in region_names() {
        let r = &regions[name];
        let area = m.area_with_tag(tag);
        total += area;
        let reported = r["area_mesh_m2"].as_f64().unwrap();
        let exact = r["area_exact_m2"].as_f64().unwrap();
        let disc = r["area_mesh_rel_err"].as_f64().unwrap();
        assert!(
            ((area - reported) / reported).abs() < 1e-12,
            "{name}: Rust area {area} vs generator {reported}"
        );
        let rel = (area - exact) / exact;
        assert!(
            (rel - disc).abs() < 1e-12 && rel.abs() < 5e-3,
            "{name}: area error vs exact NURBS {rel:e} (generator {disc:e})"
        );
    }
    let annulus = PI * (R_O * R_O - R_I * R_I) / 6.0;
    assert!(
        ((total - annulus) / annulus).abs() < 1e-4,
        "sector total {total} vs {annulus}"
    );
    // The magnet is a straight-sided MW x MH rectangle: exact on any mesh.
    assert!((m.area_with_tag(2) - 0.019 * 0.007).abs() < 1e-17);
}

#[test]
fn coupling_circle_has_uniform_matching_nodes_on_both_sides() {
    let (m, _) = load();
    let angle = |i: u32| {
        let p = m.mesh.nodes[i as usize];
        p[1].atan2(p[0])
    };
    let mut sides = Vec::new();
    for tag in [121, 122] {
        let mut nodes = m.nodes_on_line_tag(tag);
        assert_eq!(nodes.len(), N_SEGMENTS + 1, "coupling tag {tag} node count");
        assert_eq!(m.lines_with_tag(tag).len(), N_SEGMENTS);
        nodes.sort_by(|&a, &b| angle(a).total_cmp(&angle(b)));
        for (j, &n) in nodes.iter().enumerate() {
            let p = m.mesh.nodes[n as usize];
            let theta = PI / 3.0 + (PI / 3.0) * j as f64 / N_SEGMENTS as f64;
            assert!((p[0].hypot(p[1]) - R_C).abs() < 1e-15);
            assert!(
                (angle(n) - theta).abs() < 1e-13,
                "node {j} off the 0.5-degree grid"
            );
        }
        sides.push(nodes);
    }
    // Disjoint node sets (sliding band), coincident positions at angle 0.
    for (a, b) in sides[0].iter().zip(&sides[1]) {
        assert_ne!(a, b);
        let (pa, pb) = (m.mesh.nodes[*a as usize], m.mesh.nodes[*b as usize]);
        assert!((pa[0] - pb[0]).hypot(pa[1] - pb[1]) < 1e-15);
    }
}

#[test]
fn antiperiodic_edges_pair_by_sixty_degree_rotation() {
    let (m, _) = load();
    let (c, s) = ((PI / 3.0).cos(), (PI / 3.0).sin());
    for (lo, hi) in [(111, 112), (113, 114)] {
        let lo_nodes = m.nodes_on_line_tag(lo);
        let hi_nodes = m.nodes_on_line_tag(hi);
        assert_eq!(lo_nodes.len(), hi_nodes.len(), "edges {lo}/{hi}");
        for &n in &lo_nodes {
            let p = m.mesh.nodes[n as usize];
            let q = [c * p[0] - s * p[1], s * p[0] + c * p[1]];
            let best = hi_nodes
                .iter()
                .map(|&k| {
                    let r = m.mesh.nodes[k as usize];
                    (r[0] - q[0]).hypot(r[1] - q[1])
                })
                .fold(f64::INFINITY, f64::min);
            assert!(
                best < 1e-12,
                "edge {lo} node {n}: no partner on {hi} ({best:e})"
            );
        }
    }
}

/// Regenerated finer levels (gitignored; built by `build_sector_mesh.py`)
/// get the same orientation, area and coupling checks when present. In CI
/// only the pinned L0 exists, and this test checks that it was found.
#[test]
fn regenerated_levels_are_counter_clockwise_when_present() {
    let dir = geometry_dir().join("meshes");
    let mut checked = 0;
    for level in 0..4u32 {
        let path = dir.join(format!("icem_initial_sector_L{level}.msh"));
        let Ok(bytes) = std::fs::read(&path) else {
            continue;
        };
        let m = read_tagged_tri_mesh(&bytes).expect("parse level");
        let report: Value = serde_json::from_slice(
            &std::fs::read(dir.join(format!("icem_initial_sector_L{level}_report.json")))
                .expect("report"),
        )
        .expect("parse report");
        for t in 0..m.mesh.n_tris() {
            assert!(
                geode_core::mesh::tagged_tri::tri_signed_area(&m.mesh, t) > 0.0,
                "L{level} triangle {t} clockwise"
            );
        }
        let n = N_SEGMENTS << level;
        assert_eq!(
            m.nodes_on_line_tag(121).len(),
            n + 1,
            "L{level} rotor coupling"
        );
        assert_eq!(
            m.nodes_on_line_tag(122).len(),
            n + 1,
            "L{level} stator coupling"
        );
        for (name, tag) in region_names() {
            let reported = report["regions"][name]["area_mesh_m2"].as_f64().unwrap();
            let area = m.area_with_tag(tag);
            assert!(
                ((area - reported) / reported).abs() < 1e-12,
                "L{level} {name}"
            );
        }
        checked += 1;
    }
    assert!(checked >= 1, "pinned L0 mesh missing");
}
